/* Light */
:root {
  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;
  --chip-background: #e8eef9;
  --chip-text: #1b2433;
  --field-border: #7d8799;
  --field-border-error: #c4231b;
  --gap-s: 4px;
  --padding-m: 12px;
  --padding-s: 8px;
  --padding-xs: 4px;
  --radii-button: 8px;
  --radii-chip: 16px;
  --radii-field: 6px;
  --stroke-default: 1px;
  --surface-page: #ffffff;
  --text-primary: #1b2433;
}

/* Dark */
:root[data-theme="dark"] {
  --button-background: #5b8def;
  --button-background-hover: #7aa3f2;
  --button-text: #0b1020;
  --chip-background: #243049;
  --chip-text: #eef2f8;
  --field-border: #8f99ab;
  --field-border-error: #ff7a70;
  --surface-page: #10151f;
  --text-primary: #eef2f8;
}

