import './Chip.css';

export function Chip({ Size = 'M', Icon = false, Label = 'Filter', pressed = false, className, ...rest }) {
  const classes = ['chip', Size === 'L' && 'chip--l', className].filter(Boolean).join(' ');
  return (
    <button type="button" className={classes} aria-pressed={pressed ? 'true' : 'false'} {...rest}>
      {Icon && <span className="chip__icon" aria-hidden="true" />}
      {Label}
    </button>
  );
}

export default Chip;

