import './Chip.css';

/**
 * chip — a filter people switch on and off.
 * Props carry Figma's chip property names: Size (M | L), Icon (False | True), Label (text).
 */
export function Chip({ Size = 'M', Icon = false, Label = 'Filter', pressed = false, onPressedChange, className, ...rest }) {
  const classes = ['chip', Size === 'L' && 'chip--l', className].filter(Boolean).join(' ');

  return (
    <button
      type="button"
      className={classes}
      aria-pressed={pressed ? 'true' : 'false'}
      onClick={() => onPressedChange?.(!pressed)}
      {...rest}
    >
      {Icon && <span className="chip__icon" aria-hidden="true" />}
      {Label}
    </button>
  );
}

export default Chip;

