import { useId } from "react";
import "./Field.css";

/**
 * field: a one-line text input.
 * `state` uses Figma's prop name and values ("Default" | "Error").
 * Give it a `label` (sets aria-label) or pass `aria-labelledby`.
 * With state="Error", `errorMessage` is shown and linked via aria-describedby.
 */
export function Field({
  state = "Default",
  label,
  errorMessage,
  className,
  id,
  ...inputProps
}) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const errorId = `${inputId}-error`;
  const isError = state === "Error";
  const showError = isError && Boolean(errorMessage);

  const classes = ["field", isError && "field--error", className]
    .filter(Boolean)
    .join(" ");

  return (
    <>
      <input
        type="text"
        {...inputProps}
        id={inputId}
        className={classes}
        aria-label={label}
        aria-invalid={isError ? "true" : undefined}
        aria-describedby={showError ? errorId : undefined}
      />
      {showError && <span id={errorId}>{errorMessage}</span>}
    </>
  );
}

export default Field;

