import { useId } from "react";
import "../styles/tokens.css";
import "./Field.css";

/**
 * field — a one-line text input (Tidepool, Figma node 3:21).
 *
 * `state` uses Figma's own prop name and values: "Default" | "Error".
 * Figma draws no visible label, so `label` is given to the input as its
 * accessible name. In the Error state, `errorMessage` is shown and linked to
 * the input with aria-describedby.
 */
export function Field({
  state = "Default",
  label,
  errorMessage,
  className,
  id,
  ...inputProps
}) {
  const autoId = useId();
  const inputId = id ?? autoId;
  const errorId = `${inputId}-error`;
  const isError = state === "Error";
  const showError = isError && Boolean(errorMessage);

  const classes = ["field", isError && "field--error", className]
    .filter(Boolean)
    .join(" ");

  return (
    <>
      <input
        type="text"
        {...inputProps}
        id={inputId}
        className={classes}
        aria-label={label}
        aria-invalid={isError || undefined}
        aria-describedby={showError ? errorId : undefined}
      />
      {showError && (
        <span id={errorId} className="field__error">
          {errorMessage}
        </span>
      )}
    </>
  );
}

export default Field;

